import type { Rate } from "./format";
import type { GateCheckId } from "./gate";
import type { Report } from "./report";

import { format, interval } from "./format";

// The README's results section (plan M6), rendered from the test report so
// the README can't drift from eval/results/summary-test.md. `pnpm eval:report
// --part test` rewrites the section between the markers, and a unit test
// checks that the README holds exactly what this renders.

export const README_RESULTS_START =
  "<!-- results:start: generated by `pnpm eval:report --part test`; do not edit by hand -->";
export const README_RESULTS_END = "<!-- results:end -->";

function cell(rate: Rate): string {
  return `${format(rate)} (${interval(rate.ci)})`;
}

/** Each gate check as a reader would ask it. */
const GATE_QUESTIONS: Record<GateCheckId, string> = {
  type_accuracy: "Is the type accuracy at least 0.80?",
  type_vs_keywords: "Does Jev find the type clearly better than the keyword rules?",
  area_accuracy: "Is the area accuracy at least 0.60?",
  area_vs_keywords: "Does Jev find the area clearly better than the keyword rules?",
  duplicate_pick: "When the original is a candidate, does Jev pick it at least 60% of the time?",
  false_match_rate: "Does Jev link at most 10% of the tickets that duplicate nothing?",
  duplicate_vs_search: "Does Jev link more duplicates than search at the same false-match rate?",
  injection: "Does Jev flag at least 80% of injections, with at most 10% false positives?",
};

/** What "always none" or "always no" scores: nothing found. */
function zero(n: number): string {
  return `0/${n}`;
}

export function renderReadmeResults(report: Report): string {
  const { type, area, duplicates, injection, nonGoals, priority } = report;
  const rows: [string, string, string, string][] = [
    [
      "Type accuracy",
      cell(type.jev),
      `keyword rules: ${cell(type.keyword)}`,
      `majority class: ${cell(type.majority)}`,
    ],
    [
      "Area accuracy",
      cell(area.jev),
      `keyword rules: ${cell(area.keyword)}`,
      `majority class: ${cell(area.majority)}`,
    ],
    [
      "Duplicates linked to their original",
      cell(duplicates.hitRate),
      `search's top hit at Jev's false-match rate: ${cell(duplicates.search.hitRate)}`,
      `always none: ${zero(duplicates.hitRate.n)}`,
    ],
    [
      "False matches on tickets that duplicate nothing",
      cell(duplicates.falseMatchRate),
      `search's top hit: ${cell(duplicates.search.falseMatchRate)}`,
      `always none: ${zero(duplicates.falseMatchRate.n)}`,
    ],
    [
      "Prompt injections flagged",
      cell(injection.recall),
      `keyword rules: ${cell(injection.keyword.recall)}`,
      `always no: ${zero(injection.recall.n)}`,
    ],
    [
      "Benign tickets flagged as injections",
      cell(injection.falsePositiveRate),
      `keyword rules: ${cell(injection.keyword.falsePositiveRate)}`,
      `always no: ${zero(injection.falsePositiveRate.n)}`,
    ],
    [
      "Requests for a non-goal recognized",
      cell(nonGoals.correct),
      `keyword rules: ${cell(nonGoals.keyword.correct)}`,
      `always no: ${zero(nonGoals.correct.n)}`,
    ],
    [
      "Priority equals the label (directional)",
      `${cell(priority.exact)}, through the policy`,
      `the policy, given the correct answers: ${cell(priority.goldAnswersExact)}`,
      `majority class: ${cell(priority.majorityExact)}`,
    ],
  ];

  const failed = report.gate.filter(({ pass }) => !pass);
  const difference = (id: GateCheckId) => {
    const section = id === "type_vs_keywords" ? report.type : report.area;
    const value = section.difference.value ?? 0;
    return `No: the difference is ${value >= 0 ? "+" : ""}${value.toFixed(2)}, and its 95% interval (${interval(section.difference.ci)}) includes 0.`;
  };
  const gate = [
    `The go/no-go gate, fixed before the test run, passes ${report.gate.length - failed.length} of ${report.gate.length} checks.`,
    ...failed.map(({ id, value }) =>
      id === "type_vs_keywords" || id === "area_vs_keywords"
        ? ` The failed check: "${GATE_QUESTIONS[id]}" ${difference(id)}`
        : ` The failed check: "${GATE_QUESTIONS[id]}" No: ${value}.`,
    ),
  ].join("");

  const { secondRun, shuffleFlips } = report.consistency;
  const consistency = [
    secondRun ? `A second run gives the same type on ${format(secondRun.type)}.` : "",
    shuffleFlips ? ` Shuffled option order changes the type on ${format(shuffleFlips.type)}.` : "",
  ].join("");

  return [
    README_RESULTS_START,
    "",
    `Measured on the ${report.runs[0]?.items ?? 0} test tickets with \`${report.runs[0]?.model ?? "jev"}\`. Each figure is k/n = rate, with its 95% interval in parentheses.`,
    "",
    ...alignedTable(["Measure", "Jev", "Plain-code baseline", "Naive baseline"], rows),
    "",
    gate,
    "",
    `${consistency} One request per ticket takes ${Math.round(report.latency.p50)} ms at the median and ${Math.round(report.latency.p95)} ms at the 95th percentile, and 1,000 tickets cost $${report.cost.usdPer1000Tickets.toFixed(3)}.`,
    "",
    README_RESULTS_END,
  ].join("\n");
}

/** A Markdown table with padded columns, as the formatter writes it. */
function alignedTable(header: readonly string[], rows: readonly (readonly string[])[]): string[] {
  const widths = header.map((title, column) =>
    Math.max(3, title.length, ...rows.map((row) => (row[column] ?? "").length)),
  );
  const line = (cells: readonly string[]) =>
    `| ${widths.map((width, column) => (cells[column] ?? "").padEnd(width)).join(" | ")} |`;
  return [
    line(header),
    `| ${widths.map((width) => "-".repeat(width)).join(" | ")} |`,
    ...rows.map(line),
  ];
}

/** The README with its results section replaced; throws if the markers are missing. */
export function replaceReadmeResults(readme: string, report: Report): string {
  const start = readme.indexOf(README_RESULTS_START);
  const end = readme.indexOf(README_RESULTS_END);
  if (start === -1 || end === -1 || end < start) {
    throw new Error("README.md has no results markers");
  }
  return (
    readme.slice(0, start) +
    renderReadmeResults(report) +
    readme.slice(end + README_RESULTS_END.length)
  );
}

/** The README's current results section, markers included, or null. */
export function readmeResults(readme: string): string | null {
  const start = readme.indexOf(README_RESULTS_START);
  const end = readme.indexOf(README_RESULTS_END);
  if (start === -1 || end === -1 || end < start) return null;
  return readme.slice(start, end + README_RESULTS_END.length);
}
